// Generic with multiple type parameters and defaults
interface ApiResponse<TData = unknown, TError = Error> {
  data: TData | null;
  error: TError | null;
  loading: boolean;
}

// Generic hook with constraints
function useApi<TResponse extends Record<string, unknown>>(
  url: string
): ApiResponse<TResponse> {
  const [data, setData] = useState<TResponse | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(url)
      .then(res => res.json())
      .then(setData)
      .catch(setError)
      .finally(() => setLoading(false));
  }, [url]);

  return { data, error, loading };
}

