import { ComponentPropsWithoutRef, ElementRef, forwardRef } from 'react';

// Preferred pattern: explicit props without React.FC
interface ButtonProps extends ComponentPropsWithoutRef<'button'> {
  variant?: 'solid' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
}

// Forward ref with proper typing
const Button = forwardRef<ElementRef<'button'>, ButtonProps>(
  ({ variant = 'solid', size = 'md', isLoading, children, ...props }, ref) => {
    return (
      <button
        ref={ref}
        className={`btn btn--${variant} btn--${size}`}
        disabled={isLoading || props.disabled}
        {...props}
      >
        {isLoading ? <span className="spinner" /> : children}
      </button>
    );
  }
);

Button.displayName = 'Button';
export default Button;

import { ElementType, ComponentPropsWithoutRef, ReactNode } from 'react';

// Polymorphic component props
type PolymorphicProps<T extends ElementType> = {
  as?: T;
  children: ReactNode;
} & Omit<ComponentPropsWithoutRef<T>, 'as' | 'children'>;

function Text<T extends ElementType = 'span'>({
  as,
  children,
  ...props
}: PolymorphicProps<T>): JSX.Element {
  const Component = as || 'span';
  return <Component {...props}>{children}</Component>;
}

// Usage: TypeScript knows the correct props for each element
<Text as="h1" className="title">Heading</Text>
{/* h1 props are available */}

<Text as="a" href="https://example.com" target="_blank">
  Link
</Text>
{/* anchor props like href and target are available */}

<Text as="button" onClick={() => alert('clicked')} type="button">
  Click me
</Text>
{/* button props like onClick and type are available */}

